    key: `project:${project.folder}`,
    at: project.openedAt,
    title: folderName(project.folder),
    line: folderLine(project.folder),
    project,
    join: null
  }))
  const fromJoins = joins.map<Place>(join => ({
    key: `join:${join.link}`,
    at: join.joinedAt,
    title: serverName(join.link),
    line: folderName(join.folder),
    project: null,
    join
  }))
